from pathlib import Path
import json,zlib,base64,subprocess
DATA=''
files=json.loads(zlib.decompress(base64.b64decode(DATA)).decode('utf-8'))
for path,content in files.items():
 p=Path(path); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(content,encoding='utf-8')
for temp in [Path('tools/refine_demo_batch.py'),Path('.github/workflows/refine-demos.yml')]:
 if temp.exists(): temp.unlink()
subprocess.run(['git','config','user.name','Catalogo S Automation'],check=True)
subprocess.run(['git','config','user.email','actions@users.noreply.github.com'],check=True)
subprocess.run(['git','add','-A'],check=True)
if subprocess.run(['git','diff','--cached','--quiet']).returncode!=0:
 subprocess.run(['git','commit','-m','Refina demonstracoes vazias e pouco legiveis'],check=True)
 subprocess.run(['git','push'],check=True)
